/* ============================================================================
   ALMENARA · Generador del informe en PDF
   ----------------------------------------------------------------------------
   Antes el informe se sacaba por el diálogo de impresión del navegador: había
   que abrirlo, buscar el menú de destino y elegir «Guardar como PDF». Tres
   pasos y una explicación distinta para cada navegador. Ahora el archivo se
   compone aquí, en el propio navegador, y se descarga de una vez.

   Todo va alojado en el dominio. El .htaccess declara script-src 'self', así
   que no se puede cargar nada de una red de distribución ajena; y aunque se
   pudiera, la posición europea de la empresa desaconseja depender de una.

   LA TIPOGRAFÍA. Las catorce fuentes que trae el formato PDF de serie no
   cubren el cirílico, y la web se publica también en ruso. Va incrustada la
   misma Jost del sitio, recortada a los caracteres que el informe puede
   necesitar: 29 kB por peso, con el alfabeto ruso completo.

   DOS AUSENCIAS DELIBERADAS. La flecha «→» y el subíndice «₂» no existen en
   Jost. En lugar de sustituir la tipografía por otra, el informe se maqueta a
   dos columnas —actual y con Almenara—, que no necesita flecha y además se
   lee mejor en papel; y el dióxido de carbono se escribe CO2.
   ========================================================================== */

(function () {
  'use strict';

  /* --- Los dos pesos, en base64 -------------------------------------------
     Jost Light para el texto corrido y Jost Medium para los rótulos. Son los
     mismos trazos que se ven en pantalla, de modo que el PDF y la web salen
     del mismo taller. */
  const JOST_300 = '';
  const JOST_500 = '';

  /* --- Paleta, la misma del sitio ---------------------------------------- */
  const TINTA  = [16, 30, 49];
  const APAG   = [90, 107, 126];
  const FILETE = [214, 218, 223];
  const AMBAR  = [138, 78, 0];
  const AMBARV = [227, 154, 46];
  const PAPEL  = [243, 241, 236];

  /* --- Geometría de la hoja, en milímetros ------------------------------- */
  const ANCHO = 210, ALTO = 297;
  const IZQ = 20, DER = 190, CAJA = DER - IZQ;
  const PIE_LIBRE = 36;          // lo que se reserva abajo antes de saltar

  /* Caracteres que la tipografía recortada no lleva. Se sustituyen antes de
     escribir: un cuadrado vacío en mitad de una cifra queda peor que esto. */
  function seguro(t) {
    return String(t == null ? '' : t)
      .replace(/\u2082/g, '2')      // ₂
      .replace(/\u2083/g, '3')      // ₃
      .replace(/\u2192/g, '-')      // →
      // Los espacios finos separan los millares en francés y en ruso. No
      // están en el juego recortado, así que se caían y salía «102757 €».
      .replace(/[\u00a0\u202f\u2009\u2007]/g, ' ');
  }

  function nuevoDoc(jsPDF) {
    const doc = new jsPDF({ unit: 'mm', format: 'a4', compress: true });
    doc.addFileToVFS('Jost-300.ttf', JOST_300);
    doc.addFont('Jost-300.ttf', 'Jost', 'normal');
    doc.addFileToVFS('Jost-500.ttf', JOST_500);
    doc.addFont('Jost-500.ttf', 'Jost', 'bold');
    doc.setFont('Jost', 'normal');
    return doc;
  }

  /* ==========================================================================
     Utilidades de dibujo
     ========================================================================== */

  function Lienzo(doc) {
    this.doc = doc;
    this.y = 0;
  }

  Lienzo.prototype.color = function (c) { this.doc.setTextColor(c[0], c[1], c[2]); return this; };

  Lienzo.prototype.fuente = function (peso, tam, espaciado) {
    this.doc.setFont('Jost', peso === 500 ? 'bold' : 'normal');
    this.doc.setFontSize(tam);
    this.doc.setCharSpace(espaciado || 0);
    return this;
  };

  Lienzo.prototype.sitio = function (alto) {
    if (this.y + alto > ALTO - PIE_LIBRE) {
      this.doc.addPage();
      this.y = 24;
    }
    return this;
  };

  Lienzo.prototype.linea = function (y, color) {
    const c = color || FILETE;
    this.doc.setDrawColor(c[0], c[1], c[2]);
    this.doc.setLineWidth(0.2);
    this.doc.line(IZQ, y, DER, y);
    return this;
  };

  /* Escribe un párrafo partido a la anchura de la caja y devuelve lo que ha
     bajado. La interlínea se pasa en milímetros por renglón. */
  Lienzo.prototype.parrafo = function (texto, interlinea, ancho) {
    const w = ancho || CAJA;
    const trozos = this.doc.splitTextToSize(seguro(texto), w);
    for (let i = 0; i < trozos.length; i++) {
      this.sitio(interlinea);
      this.doc.text(trozos[i], IZQ, this.y);
      this.y += interlinea;
    }
    return this;
  };

  /* ==========================================================================
     El informe
     ========================================================================== */

  function componer(doc, d) {
    const L = new Lienzo(doc);

    /* --- Membrete --------------------------------------------------------- */
    L.y = 22;
    L.fuente(500, 11, 1.6).color(TINTA);
    doc.text('ALMENARA', IZQ, L.y);

    // El punto ámbar de la marca, que en la web representa la fuente de luz.
    doc.setFillColor(AMBARV[0], AMBARV[1], AMBARV[2]);
    doc.circle(IZQ - 3.6, L.y - 1.2, 0.85, 'F');

    L.fuente(300, 8, 0.3).color(APAG);
    doc.text(seguro(d.fechaEtiqueta + ': ' + d.fecha), DER, L.y, { align: 'right' });

    L.y += 4;
    L.linea(L.y);

    /* --- Título ----------------------------------------------------------- */
    L.y += 8;
    L.fuente(300, 19, -0.4).color(TINTA);
    const titulo = doc.splitTextToSize(seguro(d.titulo), CAJA);
    for (let i = 0; i < titulo.length; i++) { doc.text(titulo[i], IZQ, L.y); L.y += 7.5; }

    L.y += 0.5;
    L.fuente(300, 9.5, 0).color(APAG);
    L.parrafo(d.sub, 5, CAJA * 0.78);

    /* --- La cifra grande --------------------------------------------------- */
    L.y += 9;
    L.fuente(500, 7.5, 1.4).color(APAG);
    doc.text(seguro(d.grandeEtiqueta.toUpperCase()), IZQ, L.y);

    L.y += 10;
    L.fuente(300, 24, -0.8).color(TINTA);
    doc.text(seguro(d.grande), IZQ, L.y);

    if (typeof d.recorte === 'number') {
      L.y += 5;
      L.fuente(500, 8, 0.6).color(AMBAR);
      doc.text(seguro(d.recorteTexto), IZQ, L.y);
    }

    /* --- Las dos barras de potencia, aquí y no al final -------------------
       Estaban después del método, y decían lo mismo que la cifra grande y que
       la primera fila de la tabla: la potencia antes y después. Puestas justo
       debajo del titular, lo demuestran en lugar de repetirlo, y el documento
       deja de arrastrar una segunda hoja casi vacía. Además desaparece la
       barrita fina del recorte, que era una tercera manera de contar lo
       mismo. -------------------------------------------------------------- */
    if (d.barras) {
      L.y += 7.5;
      const b = d.barras;
      const etW = 30, valW = 26;
      const pistaX = IZQ + etW, pistaW = CAJA - etW - valW;

      function barra(etiqueta, valor, proporcion, ambar) {
        L.sitio(9);
        L.fuente(300, 7.5, 0.5).color(APAG);
        doc.text(seguro(etiqueta), IZQ, L.y + 2.6);
        doc.setFillColor(PAPEL[0], PAPEL[1], PAPEL[2]);
        doc.rect(pistaX, L.y, pistaW, 3.4, 'F');
        if (ambar) doc.setFillColor(AMBARV[0], AMBARV[1], AMBARV[2]);
        else doc.setFillColor(TINTA[0], TINTA[1], TINTA[2]);
        doc.rect(pistaX, L.y, pistaW * Math.max(0.004, Math.min(1, proporcion)), 3.4, 'F');
        L.fuente(500, 9, 0).color(TINTA);
        doc.text(seguro(valor), DER, L.y + 3, { align: 'right' });
        L.y += 9;
      }
      barra(b.antesEtiqueta, b.antesValor, 1, false);
      barra(b.despuesEtiqueta, b.despuesValor, b.proporcion, true);
      L.y -= 3;
    }

    /* --- Datos facilitados -------------------------------------------------- */
    L.y += 6;
    rotulo(L, d.tituloEntradas);

    // Dos columnas de fichas. Cada una lleva la etiqueta pequeña arriba y el
    // valor debajo, como en la portada de una ficha técnica.
    const colW = CAJA / 2;
    let fila = 0;
    for (let i = 0; i < d.entradas.length; i += 2) {
      L.sitio(9.6);
      const par = [d.entradas[i], d.entradas[i + 1]];
      for (let c = 0; c < 2; c++) {
        if (!par[c]) continue;
        const x = IZQ + c * colW;
        L.fuente(300, 7.5, 0.4).color(APAG);
        doc.text(seguro(par[c][0]), x, L.y);
        L.fuente(500, 10.5, 0).color(TINTA);
        doc.text(seguro(par[c][1]), x, L.y + 5.5);
      }
      L.y += 9.6;
      fila++;
    }

    /* --- Resultado ---------------------------------------------------------- */
    L.y += 3;
    rotulo(L, d.tituloResultado);

    // Cabecera de la tabla: concepto, situación actual, con Almenara.
    const cx1 = IZQ, cx2 = IZQ + CAJA * 0.52, cx3 = DER;
    L.sitio(10);
    L.fuente(500, 7, 0.9).color(APAG);
    // La primera columna no lleva rótulo. Llevaba el mismo que el de la
    // sección, «Resultado» encima de «Resultado», que no informa de nada.
    doc.text(seguro(d.colAntes.toUpperCase()), cx2, L.y);
    doc.text(seguro(d.colDespues.toUpperCase()), cx3, L.y, { align: 'right' });
    L.y += 2.6;
    L.linea(L.y, [180, 186, 194]);
    L.y += 6;

    for (let i = 0; i < d.filas.length; i++) {
      const f = d.filas[i];
      L.sitio(6.4);
      const destacada = !!f[3];
      L.fuente(destacada ? 500 : 300, 9, 0).color(destacada ? TINTA : APAG);
      doc.text(seguro(f[0]), cx1, L.y);
      L.fuente(300, 9, 0).color(APAG);
      if (f[1]) doc.text(seguro(f[1]), cx2, L.y);
      L.fuente(destacada ? 500 : 300, 9, 0).color(TINTA);
      doc.text(seguro(f[2]), cx3, L.y, { align: 'right' });
      L.y += 2.2;
      L.linea(L.y);
      L.y += 4.2;
    }

    /* --- Método -------------------------------------------------------------- */
    L.y += 7;
    // El método no se parte por la mitad. Antes se quedaban dos renglones
    // huérfanos abriendo una segunda hoja, que es el peor corte posible.
    L.fuente(300, 8, 0).color(APAG);
    const lineasMetodo = doc.splitTextToSize(seguro(d.metodo), CAJA).length;
    L.sitio(11 + lineasMetodo * 4.2);
    rotulo(L, d.tituloMetodo);
    L.fuente(300, 8, 0).color(APAG);
    L.parrafo(d.metodo, 4.2);

    /* --- Pie, siempre al fondo de la última hoja ------------------------------ */
    const yPie = ALTO - 26;
    if (L.y > yPie - 6) { doc.addPage(); L.y = 24; }
    L.linea(yPie - 8);

    // Tres renglones apilados y no dos columnas: «Prepared by» mide una cosa
    // en inglés y otra muy distinta en alemán, y con columnas se solapaban.
    L.fuente(500, 6.8, 1.2).color(APAG);
    doc.text(seguro(d.pieEtiqueta.toUpperCase()), IZQ, yPie - 5);
    L.fuente(500, 8.5, 0.3).color(TINTA);
    doc.text('Almenara  ·  Madrid', IZQ, yPie);
    L.fuente(300, 7.5, 0).color(APAG);
    doc.text(seguro(d.contacto), IZQ, yPie + 4);

    L.fuente(300, 6.5, 0).color(APAG);
    const aviso = doc.splitTextToSize(seguro(d.aviso), CAJA);
    let ya = yPie + 11;
    for (let i = 0; i < aviso.length && i < 3; i++) { doc.text(aviso[i], IZQ, ya); ya += 3; }

    /* --- Numeración, si pasa de una hoja --------------------------------------- */
    const hojas = doc.getNumberOfPages();
    if (hojas > 1) {
      for (let p = 1; p <= hojas; p++) {
        doc.setPage(p);
        doc.setFont('Jost', 'normal');
        doc.setFontSize(7);
        doc.setCharSpace(0.5);
        doc.setTextColor(APAG[0], APAG[1], APAG[2]);
        doc.text(p + ' / ' + hojas, DER, ALTO - 10, { align: 'right' });
      }
    }
  }

  function rotulo(L, texto) {
    L.sitio(11);
    L.fuente(500, 7.5, 1.4).color(APAG);
    L.doc.text(seguro(texto.toUpperCase()), IZQ, L.y);
    L.y += 2.4;
    L.linea(L.y, [180, 186, 194]);
    L.y += 6;
  }

  /* ==========================================================================
     Nombre del archivo
     Sin acentos ni espacios: hay gestores de correo y de archivos que todavía
     los estropean, y un adjunto con el nombre roto da mala impresión.
     ========================================================================== */
  function nombre(titulo) {
    const hoy = new Date();
    const dd = ('0' + hoy.getDate()).slice(-2);
    const mm = ('0' + (hoy.getMonth() + 1)).slice(-2);
    const base = String(titulo || 'informe')
      .normalize ? String(titulo || 'informe').normalize('NFD').replace(/[\u0300-\u036f]/g, '') : String(titulo || 'informe');
    const limpio = base.toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 40);
    // En ruso el título no deja ni una letra latina. Antes salía la palabra
    // «informe» en español dentro de un documento en cirílico.
    return 'Almenara-' + (limpio ? limpio + '-' : '') + hoy.getFullYear() + mm + dd + '.pdf';
  }

  /* ==========================================================================
     Interfaz pública
     ========================================================================== */
  window.ALMENARA_PDF = function (datos) {
    const raiz = window.jspdf || {};
    const jsPDF = raiz.jsPDF;
    if (!jsPDF) return false;
    try {
      const doc = nuevoDoc(jsPDF);
      componer(doc, datos);
      doc.save(nombre(datos.titulo));
      return true;
    } catch (e) {
      return false;
    }
  };
})();
